import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import pytest
from kasa_cevir import turkce_buyut, turkce_kucult

def test_buyut_i_harfi():
    assert turkce_buyut("i") == "\u0130"

def test_buyut_noktasiz_i():
    assert turkce_buyut("\u0131") == "I"

def test_buyut_turkce_karakterler():
    assert turkce_buyut("\u00e7\u011f\u00f6\u015f\u00fc") == "\u00c7\u011e\u00d6\u015e\u00dc"

def test_buyut_ornek_kelime():
    assert turkce_buyut("kedi") == "KED\u0130"

def test_kucult_noktali_I():
    assert turkce_kucult("\u0130") == "i"

def test_kucult_noktasiz_I():
    assert turkce_kucult("I") == "\u0131"

def test_kucult_c_cedilla_ayrimi():
    assert turkce_kucult("C") == "c"
    assert turkce_kucult("\u00c7") == "\u00e7"
    assert turkce_kucult("C\u00c7") == "c\u00e7"

def test_kucult_ornek_kelime():
    assert turkce_kucult("KED\u0130") == "kedi"

def test_bos_dize_buyut():
    assert turkce_buyut("") == ""

def test_bos_dize_kucult():
    assert turkce_kucult("") == ""

def test_sadece_bosluk_buyut():
    assert turkce_buyut("   ") == "   "

def test_sadece_bosluk_kucult():
    assert turkce_kucult("   ") == "   "

def test_koruma_buyut():
    s = "abc123! \U0001F600"
    r = turkce_buyut(s)
    assert r == "ABC123! \U0001F600"
    assert len(r) == len(s)

def test_koruma_kucult():
    s = "ABC123! \U0001F600"
    r = turkce_kucult(s)
    assert r == "abc123! \U0001F600"
    assert len(r) == len(s)

def test_uzunluk_degismez():
    assert len(turkce_buyut("i\u0131a\u00e7\U0001F600")) == len("i\u0131a\u00e7\U0001F600")
    assert len(turkce_kucult("\u0130IABC\U0001F600")) == len("\u0130IABC\U0001F600")

def test_hata_buyut_int():
    with pytest.raises(TypeError):
        turkce_buyut(123)

def test_hata_kucult_none():
    with pytest.raises(TypeError):
        turkce_kucult(None)

def test_hata_liste_ve_none():
    with pytest.raises(TypeError):
        turkce_buyut(None)
    with pytest.raises(TypeError):
        turkce_kucult(["a"])
    with pytest.raises(TypeError):
        turkce_buyut(3.14)

def test_idempotent_buyut():
    assert turkce_buyut("ABC\u00c7\u011e\u0130I\u00d6\u015e\u00dc") == "ABC\u00c7\u011e\u0130I\u00d6\u015e\u00dc"
    ilk = turkce_buyut("kedi \u0131l\u0131k \u00e7\u011f\u00f6\u015f\u00fc")
    assert turkce_buyut(ilk) == ilk

def test_idempotent_kucult():
    assert turkce_kucult("abc\u00e7\u011fi\u0131\u00f6\u015f\u00fc") == "abc\u00e7\u011fi\u0131\u00f6\u015f\u00fc"
    ilk = turkce_kucult("KED\u0130 ISTANBUL")
    assert turkce_kucult(ilk) == ilk

def test_baglamsiz_donusum():
    assert turkce_kucult("\u0130A") == "ia"
    assert turkce_buyut("\u0130a") == "\u0130A"
    assert turkce_buyut("i\u0131") == "\u0130I"

