import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
from toplu_denetim import toplu_denetle

def _iban_ok(iban):
    t = iban[4:] + iban[:4]
    n = ''
    for ch in t:
        n += ch if ch.isdigit() else str(ord(ch) - 55)
    return int(n) % 97 == 1

def gecerli_iban_bul():
    bban = '0006100519786457841326'
    for cc in range(100):
        ib = f'TR{cc:02d}{bban}'
        if _iban_ok(ib):
            return ib
    raise AssertionError('iban bulunamadi')

GIBAN = gecerli_iban_bul()
GTC = '10000000146'
GVKN = '1234567899'
GTEL = '05321234567'
GPLAKA = '34AB123'

def rec(tur=GTC, iban=None, tel=GTEL, plaka=GPLAKA, t='TC'):
    return {'tur': t, 'kimlik_no': tur, 'iban': iban or GIBAN, 'telefon': tel, 'plaka': plaka}

def test_bos_liste():
    r = toplu_denetle([])
    assert r == {'toplam': 0, 'gecerli_sayisi': 0, 'gecersiz_sayisi': 0, 'hatalar': []}

def test_none_typeerror():
    try:
        toplu_denetle(None)
        assert False
    except TypeError:
        pass

def test_string_typeerror():
    try:
        toplu_denetle('liste')
        assert False
    except TypeError:
        pass

def test_dict_typeerror():
    try:
        toplu_denetle({})
        assert False
    except TypeError:
        pass

def test_int_typeerror():
    try:
        toplu_denetle(123)
        assert False
    except TypeError:
        pass

def test_gecerli_tc():
    r = toplu_denetle([rec()])
    assert r['toplam'] == 1 and r['gecerli_sayisi'] == 1 and r['gecersiz_sayisi'] == 0 and r['hatalar'] == []

def test_gecerli_vkn():
    r = toplu_denetle([rec(GVKN, t='VKN')])
    assert r['gecerli_sayisi'] == 1 and r['hatalar'] == []

def test_gecersiz_tur():
    r = toplu_denetle([rec(t='XX')])
    assert r['gecersiz_sayisi'] == 1
    assert r['hatalar'][0] == {'indeks': 0, 'kod': 'tur_hatası'}

def test_eksik_anahtar():
    k = {'tur': 'TC', 'kimlik_no': GTC, 'iban': GIBAN, 'telefon': GTEL}
    r = toplu_denetle([k])
    assert r['toplam'] == 1 and r['gecersiz_sayisi'] == 1
    assert r['hatalar'][0]['indeks'] == 0 and 'kod' in r['hatalar'][0]

def test_dict_olmayan():
    r = toplu_denetle(['string-kayit'])
    assert r['gecersiz_sayisi'] == 1
    assert r['hatalar'][0] == {'indeks': 0, 'kod': 'tur_hatası'}

def test_deger_turu():
    k = {'tur': 'TC', 'kimlik_no': 10000000146, 'iban': GIBAN, 'telefon': GTEL, 'plaka': GPLAKA}
    r = toplu_denetle([k])
    assert r['gecersiz_sayisi'] == 1
    assert r['hatalar'][0]['kod'] == 'tur_hatası'

def test_tc_hatasi():
    r = toplu_denetle([rec('11111111111')])
    assert r['hatalar'][0]['kod'] == 'kimlik_no_hatası'

def test_vkn_hatasi():
    r = toplu_denetle([rec('1234567890', t='VKN')])
    assert r['hatalar'][0]['kod'] == 'kimlik_no_hatası'

def test_iban_hatasi():
    kotu = GIBAN[:-1] + ('0' if GIBAN[-1] != '0' else '1')
    assert not _iban_ok(kotu)
    r = toplu_denetle([rec(iban=kotu)])
    assert r['hatalar'][0]['kod'] == 'iban_hatası'

def test_telefon_hatasi():
    r = toplu_denetle([rec(tel='12345')])
    assert r['hatalar'][0]['kod'] == 'telefon_hatası'

def test_plaka_hatasi():
    r = toplu_denetle([rec(plaka='99ZZZ99999')])
    assert r['hatalar'][0]['kod'] == 'plaka_hatası'

def test_oncelik_kimlik():
    kotu = GIBAN[:-1] + ('0' if GIBAN[-1] != '0' else '1')
    r = toplu_denetle([rec('11111111111', iban=kotu, tel='000', plaka='gecersiz')])
    assert r['hatalar'][0]['kod'] == 'kimlik_no_hatası'

def test_oncelik_iban():
    kotu = GIBAN[:-1] + ('0' if GIBAN[-1] != '0' else '1')
    r = toplu_denetle([rec(iban=kotu, tel='000', plaka='gecersiz')])
    assert r['hatalar'][0]['kod'] == 'iban_hatası'

def test_oncelik_telefon():
    r = toplu_denetle([rec(tel='000', plaka='gecersiz')])
    assert r['hatalar'][0]['kod'] == 'telefon_hatası'

def test_siralama():
    kotu = GIBAN[:-1] + ('0' if GIBAN[-1] != '0' else '1')
    k0 = rec(tel='000')
    k1 = rec(iban=kotu)
    k2 = rec('11111111111')
    r = toplu_denetle([k0, k1, k2])
    kodlar = [h['kod'] for h in r['hatalar']]
    assert kodlar == sorted(kodlar)
    assert r['hatalar'][0] == {'indeks': 1, 'kod': 'iban_hatası'}
    assert r['hatalar'][1] == {'indeks': 2, 'kod': 'kimlik_no_hatası'}
    assert r['hatalar'][2] == {'indeks': 0, 'kod': 'telefon_hatası'}

def test_plaka_turkce_i():
    r = toplu_denetle([rec(plaka='34aib12')])
    assert r['gecersiz_sayisi'] == 1
    assert r['hatalar'][0]['kod'] == 'plaka_hatası'

def test_plaka_kucuk_harf_gecerli():
    r = toplu_denetle([rec(plaka='34ab123')])
    assert r['gecerli_sayisi'] == 1 and r['hatalar'] == []

def test_devam_eder_sayilar():
    k_ok = rec()
    k_bad = rec('11111111111')
    r = toplu_denetle([k_bad, k_ok, 123])
    assert r['toplam'] == 3 and r['gecerli_sayisi'] == 1 and r['gecersiz_sayisi'] == 2
    assert set(r.keys()) == {'toplam', 'gecerli_sayisi', 'gecersiz_sayisi', 'hatalar'}

import sys, pathlib; sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import ast
