import pytest
from kart import MusteriKart

def _s(x: str) -> str:
    return x.replace(chr(39), '').replace('\u2019', '').replace('`', '')

def test_tam_unvan_basit():
    assert MusteriKart('ahmet').tam_unvan() == 'Ahmet'

def test_tam_unvan_kucuk_i():
    assert MusteriKart('ismail').tam_unvan() == '\u0130smail'

def test_tam_unvan_buyuk_I():
    assert MusteriKart('ILICA').tam_unvan() == 'Il\u0131ca'

def test_tam_unvan_coklu_bosluk():
    assert MusteriKart('mehmet   ali').tam_unvan() == 'Mehmet Ali'

def test_tam_unvan_bas_son_bosluk():
    assert MusteriKart('  ay\u015fe  ').tam_unvan() == 'Ay\u015fe'

def test_tam_unvan_tire():
    assert MusteriKart('mehmet-ali').tam_unvan() == 'Mehmet-Ali'

def test_tam_unvan_tek_harf():
    assert MusteriKart('a').tam_unvan() == 'A'
    assert MusteriKart('a b').tam_unvan() == 'A B'

def test_hitap_sessiz_kalin_a():
    k = MusteriKart('osman')
    assert _s(k.hitap(True)) == 'Say\u0131n Osmana'

def test_hitap_sessiz_ince_e():
    k = MusteriKart('mehmet')
    assert _s(k.hitap(True)) == 'Say\u0131n Mehmete'

def test_hitap_unlu_kalin_y():
    k = MusteriKart('mustafa')
    assert _s(k.hitap(True)) == 'Say\u0131n Mustafaya'

def test_hitap_unlu_ince_y():
    k = MusteriKart('ay\u015fe')
    assert _s(k.hitap(True)) == 'Say\u0131n Ay\u015feye'

def test_hitap_yonelme_false():
    k = MusteriKart('  mehmet   ali ')
    assert k.hitap(False) == 'Mehmet Ali'
    assert 'Say\u0131n' not in k.hitap(False)

def test_hitap_varsayilan_true():
    k = MusteriKart('osman')
    assert _s(k.hitap()) == _s(k.hitap(True))
    assert k.hitap().startswith('Say\u0131n ')

def test_hitap_tek_harf_ek():
    k = MusteriKart('a')
    assert _s(k.hitap(True)) == 'Say\u0131n Aya'

