def test_yasak_moduller_yok():
    src = pathlib.Path(__file__).resolve().parent.parent.joinpath('kart.py').read_text(encoding='utf-8')
    tree = ast.parse(src)
    yasak = {'socket', 'requests', 'urllib', 'urllib.request', 'random', 'time', 'datetime'}
    bulunan = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                bulunan.add(a.name.split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            if node.module:
                bulunan.add(node.module.split('.')[0])
    assert bulunan.isdisjoint(yasak)

